def _stat_return_kwargs(fn):
    """Pin a statsmodels test's RETURN SHAPE explicitly.

    adfuller() and kpss() warn that the plain tuple they return today becomes a result object
    in statsmodels 0.16. Passing the flag by name states which shape this notebook expects, so
    a later statsmodels cannot silently change what `[1]` means. The flag name is PROBED
    rather than hardcoded, because it differs across the versions Colab ships and an unknown
    keyword would be a TypeError on an older one.
    """
    import inspect
    p = inspect.signature(fn).parameters
    return {k: False for k in ("store", "result_object") if k in p}


ADF_KW, KPSS_KW = _stat_return_kwargs(adfuller), _stat_return_kwargs(kpss)

