# --- diagnostics: warnings are captured and counted, never silenced ----------------------
FIT_LOG, FAILURES, CLIP_LOG, LEDGER, NOTES = [], [], [], [], []
_LOG_LOCK = threading.Lock()


@contextlib.contextmanager
def capture_warnings(context):
    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter("always")
        yield
    with _LOG_LOCK:
        for w in caught:
            FIT_LOG.append({"context": context, "category": w.category.__name__,
                            "message": str(w.message).split("\n")[0][:160]})


def log_failure(context, exc):
    with _LOG_LOCK:
        FAILURES.append({"context": context, "error": type(exc).__name__,
                         "message": str(exc)[:200]})


def note(kind, msg):
    """Anything the reader must act on. Re-printed as a checklist in Section 13."""
    with _LOG_LOCK:
        NOTES.append({"kind": kind, "message": msg})
    print(f"[{kind}] {msg}")


def small_sample(n, what, floor=None):
    """One-line caveat wherever an estimate rests on fewer than MIN_ORIGINS_WARN origins."""
    floor = int(CONFIG["MIN_ORIGINS_WARN"]) if floor is None else int(floor)
    if n is not None and np.isfinite(n) and n < floor:
        return f"  [SMALL SAMPLE: {what} rests on {int(n)} origin(s), below {floor}]"
    return ""


def warning_summary():
    if not FIT_LOG:
        return pd.DataFrame(columns=["context", "category", "message", "count"])
    return (pd.DataFrame(FIT_LOG).groupby(["context", "category", "message"]).size()
            .reset_index(name="count").sort_values("count", ascending=False))


# --- disk cache: search results survive a re-run, keyed on a hash of their own inputs -----
